<?php
namespace App\Controllers\Admin;
use App\Core\Controller;use App\Core\Auth;use App\Core\Database;use App\Core\Session;use App\Core\Audit;
final class SocialAdminController extends Controller
{
 public function index():void{$u=Auth::requireAdmin();Auth::enforce('manage_settings');$total=(int)(Database::one('SELECT COUNT(*) c FROM social_links')['c']??0);$p=admin_pager($total,20);$rows=Database::all('SELECT * FROM social_links ORDER BY sort_order,id LIMIT '.$p['per_page'].' OFFSET '.$p['offset']);$this->view('admin/social',['user'=>$u,'links'=>$rows,'pagination'=>$p,'adminTitle'=>'Social Media'],'admin');}
 public function save():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_settings');$id=(int)($_POST['id']??0);$platform=substr(trim($_POST['platform']??''),0,80);$label=substr(trim($_POST['label']??''),0,100);$url=trim($_POST['url']??'');$icon=social_platform_key($platform,$url);if(strlen($platform)<2||!filter_var($url,FILTER_VALIDATE_URL)){Session::flash('error','Platform and a valid https:// URL are required.');redirect('admin/social');}if(!preg_match('~^https://~i',$url)){Session::flash('error','For security, social links must use HTTPS.');redirect('admin/social');}$active=isset($_POST['is_active'])?1:0;$sort=(int)($_POST['sort_order']??0);if($id){Database::exec('UPDATE social_links SET platform=?,label=?,url=?,icon=?,is_active=?,sort_order=?,updated_by=? WHERE id=?',[$platform,$label,$url,$icon,$active,$sort,(int)$u['id'],$id]);}else{$id=Database::insert('INSERT INTO social_links(platform,label,url,icon,is_active,sort_order,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?)',[$platform,$label,$url,$icon,$active,$sort,(int)$u['id'],(int)$u['id']]);}Audit::write((int)$u['id'],'SOCIAL_SAVED','social_links',$id,'Social media link saved');Session::flash('success','Social media link saved.');redirect('admin/social');}
 public function delete():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_settings');$id=(int)($_POST['id']??0);Database::exec('DELETE FROM social_links WHERE id=?',[$id]);Audit::write((int)$u['id'],'DELETE','social_links',$id,'Social media link deleted');Session::flash('success','Social media link deleted.');redirect('admin/social');}
}
